const STAGE_THRESHOLDS = [1, 3, 8, 15, 25, 40];
const STAGE_LABELS = [
  '씨앗을 심었어요',
  '작은 새싹이 돋았어요',
  '어린 나무가 되었어요',
  '가지가 뻗어가고 있어요',
  '잎이 무성해지고 있어요',
  '풍성한 나무가 되었어요',
  '우리 셀의 나무가 활짝 무성해요',
];

function getStage(score) {
  let stage = 0;
  STAGE_THRESHOLDS.forEach((t) => {
    if (score >= t) stage += 1;
  });
  return Math.min(stage, STAGE_THRESHOLDS.length);
}

